record.field:
# IDs to update in product.template ids_true = [22499, 22500, 22501] ids_false = [22404, 22405, 22407]
templates_true = env["product.template"].browse(ids_true).exists() templates_false = env["product.template"].browse(ids_false).exists()
if templates_true: templates_true.write({"available_in_pos": True})
if templates_false: templates_false.write({"available_in_pos": False})

BATCH_SIZE = 200

records = env['product.template'].search([('categ_id', '!=', False)])

updates = {}
for record in records:
    categ = record.categ_id

    vals = {}
    if categ.property_account_income_categ_id:
        vals["property_account_income_id"] = categ.property_account_income_categ_id.id
    if categ.property_account_expense_categ_id:
        vals["property_account_expense_id"] = categ.property_account_expense_categ_id.id

    if vals:
        key = tuple(sorted(vals.items()))
        if key not in updates:
            updates[key] = (vals, [])
        updates[key][1].append(record.id)

for key, (vals, record_ids) in updates.items():
    for i in range(0, len(record_ids), BATCH_SIZE):
        batch_ids = record_ids[i:i + BATCH_SIZE]
        env['product.template'].browse(batch_ids).write(vals)
